import sys

def main():
    line = sys.stdin.readline()
    words = line.strip().split()
    if len(words) == 0:
        print("")
    elif len(words) == 1:
        print(words[0])
    else:
        str1 = list(words[0])
        str2 = words[1]

        len_str1 = 0
        for _ in str1:
            len_str1 += 1

        str1 = str1 + [''] * (len_str1 + len(str2) + 1)

        for i in range(len(str2)):
            str1[len_str1 + i] = str2[i]

        str1[len_str1 + len(str2)] = ''

        result = ''.join(str1)
        print(result)

if __name__ == "__main__":
    main()
